{
  "measure_id": "MEAS-D6FD5BF4",
  "restatements": [
    {
      "clause_id": "§1",
      "text": "Allows parents of children eligible for public school to open education savings accounts. Requires the state to fund these accounts with 90 percent of the state per-pupil amount that the child's resident public school district would have otherwise received."
    },
    {
      "clause_id": "§2",
      "text": "Permits the funds in the education savings accounts to be spent on private school tuition, tutoring, textbooks, and approved online courses."
    }
  ],
  "findings": [
    {
      "id": "f1",
      "clause_id": "§2",
      "concern_id": "C41",
      "effect": "advances",
      "direction": null,
      "quote": "Account funds may be used for private school tuition, tutoring, textbooks, and approved online courses.",
      "mechanism": "Expands public funding for educational alternatives by allowing state funds to pay for private school tuition and other non-district educational services.",
      "certainty": "stated"
    },
    {
      "id": "f2",
      "clause_id": "§1",
      "concern_id": "C42",
      "effect": "costs",
      "direction": null,
      "quote": "The state shall deposit into the account 90 percent of the state per-pupil funding the child's resident district would otherwise receive.",
      "mechanism": "Reduces resources for district schools by diverting 90 percent of a participating student's state per-pupil funding away from the resident district and into a private account.",
      "certainty": "stated"
    }
  ],
  "analysis": [
    {
      "clause_id": "§1",
      "question_id": "Q1",
      "answer": "Under current law, state education funds are distributed only to public school districts and charter schools. This measure changes that by allowing state education funds to be diverted into private education savings accounts controlled by parents.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q2",
      "answer": "Direct costs include the 90 percent of per-pupil funding transferred to the accounts. A significant hidden cost arises if children already attending private schools (who are still 'eligible to attend public school') claim the funds, requiring the state to pay for students it previously did not subsidize. There are also administrative costs to manage the accounts and approve expenses.",
      "disputed": false
    },
    {
      "clause_id": "§2",
      "question_id": "Q3",
      "answer": "Families who choose private education or alternative services benefit from subsidized costs. Private schools and education service vendors benefit from a new revenue stream. Public school districts bear the cost through lost per-pupil state funding, though they no longer have to educate the participating student.",
      "disputed": false
    },
    {
      "clause_id": "§2",
      "question_id": "Q4",
      "answer": "Parents currently paying for private school out-of-pocket will be highly incentivized to open these accounts. Private schools may raise tuition prices to capture the new state subsidy. New businesses offering tutoring or online courses may form to attract the account funds. Public schools may need to cut budgets or consolidate programs as enrollment and funding decline.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q5",
      "answer": "It addresses the lack of publicly funded educational options for families who wish to leave the public school system. The mechanism provides a direct state subsidy to those families. However, it may create a perverse incentive for education vendors to inflate prices, and it may not fully address access issues if private tuition exceeds the account balance.",
      "disputed": false
    },
    {
      "clause_id": "§2",
      "question_id": "Q6",
      "answer": "Parents gain discretion over a portion of state education funding. Private schools, tutors, and online education vendors gain access to a new pool of state money. The state body assigned to approve courses and oversee expenditures gains administrative power.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q7",
      "answer": "Researchers disagree on the effects of education savings accounts and vouchers. Some find that they improve student outcomes through increased competition and by allowing better matching of students to schools. Others find that they harm public school finances by draining variable revenue while fixed costs remain, and that students using vouchers sometimes experience learning loss.",
      "disputed": true
    }
  ],
  "flags": [
    {
      "clause_id": "§2",
      "flag_id": "F3",
      "quote": "approved online courses",
      "note": "The actual availability of online options depends on future administrative decisions to define what constitutes an 'approved' course and which agency conducts the approvals."
    }
  ],
